import{_ as e,c as i,o as t,a2 as a}from"./chunks/framework._4mWlOLd.js";const r=JSON.parse('{"title":"Project Overview - Core Goals","description":"","frontmatter":{"layout":"doc","title":"Project Overview - Core Goals"},"headers":[],"relativePath":"docs/quicklinker-zeroRPM/project-overview/core-goals.md","filePath":"docs/quicklinker-zeroRPM/project-overview/core-goals.md","lastUpdated":1741723016000}');const o=e({name:"docs/quicklinker-zeroRPM/project-overview/core-goals.md"},[["render",function(e,r,o,s,n,l){return t(),i("div",null,r[0]||(r[0]=[a('<h1 id="core-goals-of-quicklinker-zerorpm" tabindex="-1">Core Goals of QuickLinker-ZeroRPM <a class="header-anchor" href="#core-goals-of-quicklinker-zerorpm" aria-label="Permalink to &quot;Core Goals of QuickLinker-ZeroRPM&quot;">​</a></h1><p>QuickLinker-ZeroRPM isn’t just a URL shortener—it’s an experiment in pushing lightweight technologies to their limits. The project is anchored by four core goals: <strong>cost efficiency</strong>, <strong>scalability</strong>, <strong>reliability</strong>, and <strong>learning focus</strong>. These objectives drive every architectural decision, from choosing SQLite over PostgreSQL or MongoDB to leveraging Oracle’s free tier and Redis caching. Below, each goal is unpacked with its motivation, implementation strategy, and real-world implications.</p><h2 id="_1-cost-efficiency" tabindex="-1">1. Cost Efficiency <a class="header-anchor" href="#_1-cost-efficiency" aria-label="Permalink to &quot;1. Cost Efficiency&quot;">​</a></h2><h3 id="motivation" tabindex="-1">Motivation <a class="header-anchor" href="#motivation" aria-label="Permalink to &quot;Motivation&quot;">​</a></h3><p>Running a high-performance URL shortener shouldn’t break the bank. The goal is to achieve <strong>$0/month infrastructure costs</strong>, making this a viable side project or proof-of-concept that scales without financial overhead.</p><h3 id="strategy" tabindex="-1">Strategy <a class="header-anchor" href="#strategy" aria-label="Permalink to &quot;Strategy&quot;">​</a></h3><ul><li><strong>SQLite Over Server-Based Databases</strong>: SQLite’s embedded nature eliminates the need for a separate server process, unlike PostgreSQL or MongoDB’s 3-node replica sets (costing $15+/month in cloud setups). It runs as a single file on a VM, reducing resource demands.</li><li><strong>Oracle Always Free Tier</strong>: Hosting on Oracle’s Arm-based VMs (4 cores, 24 GB RAM, 200 GB storage) provides enterprise-grade compute at no cost, with 4 Gbps bandwidth dwarfing the project’s 13.33 Mbps need for 100,000 RPM (<a href="https://www.oracle.com/in/cloud/free/faq/" target="_blank" rel="noreferrer">Oracle Free Tier FAQ</a>).</li><li><strong>Minimal Footprint</strong>: With Redis caching 99% of reads, SQLite handles only ~1,990 operations/minute (~33/second), keeping CPU and memory usage low on a free VM (<a href="https://www.reddit.com/r/selfhosted/comments/15q1o59/is_oracle_cloud_free_tier_actually_free_tier/" target="_blank" rel="noreferrer">Reddit Discussion</a>).</li></ul><h3 id="implications" tabindex="-1">Implications <a class="header-anchor" href="#implications" aria-label="Permalink to &quot;Implications&quot;">​</a></h3><p>This approach challenges the norm of pricey cloud setups, proving that a $0 budget can support significant workloads. It’s a practical lesson in resource optimization for system engineers.</p><h2 id="_2-scalability" tabindex="-1">2. Scalability <a class="header-anchor" href="#_2-scalability" aria-label="Permalink to &quot;2. Scalability&quot;">​</a></h2><h3 id="motivation-1" tabindex="-1">Motivation <a class="header-anchor" href="#motivation-1" aria-label="Permalink to &quot;Motivation&quot;">​</a></h3><p>Handling <strong>100,000 requests per minute (RPM)</strong> on a single node is ambitious, especially with SQLite, often dismissed as a “toy” database. This goal tests how far optimization and caching can stretch a lightweight stack.</p><h3 id="strategy-1" tabindex="-1">Strategy <a class="header-anchor" href="#strategy-1" aria-label="Permalink to &quot;Strategy&quot;">​</a></h3><ul><li><strong>Redis Caching</strong>: Leveraging the 80/20 rule (80% of traffic hits 20% of URLs), Redis caches 99% of redirects, reducing database load to ~990 reads and 1,000 writes per minute. Real-world data from bit.ly (33M clicks/day, ~23,000 RPM) suggests low write loads (~230 new URLs/minute), supporting this model.</li><li><strong>SQLite Tuning</strong>: Optimizations like Write-Ahead Logging (WAL), synchronous normal mode, and memory mapping push SQLite to 80,000 inserts/second and 100,000 SELECTs/second (<a href="https://phiresky.github.io/blog/2020/sqlite-performance-tuning/" target="_blank" rel="noreferrer">SQLite Performance Tuning</a>), far exceeding the ~33 operations/second needed.</li><li><strong>Phase Evolution</strong>: Starts with PostgreSQL for Phase 1’s 100 req/s, pivots to SQLite for cost, and scales with LiteFS replication in Phase 3.</li></ul><h3 id="implications-1" tabindex="-1">Implications <a class="header-anchor" href="#implications-1" aria-label="Permalink to &quot;Implications&quot;">​</a></h3><p>Achieving 100,000 RPM with SQLite redefines its production potential, offering a scalable blueprint for read-heavy apps with minimal writes—perfect for URL shorteners.</p><h2 id="_3-reliability" tabindex="-1">3. Reliability <a class="header-anchor" href="#_3-reliability" aria-label="Permalink to &quot;3. Reliability&quot;">​</a></h2><h3 id="motivation-2" tabindex="-1">Motivation <a class="header-anchor" href="#motivation-2" aria-label="Permalink to &quot;Motivation&quot;">​</a></h3><p>A URL shortener must be <strong>99.9% reliable</strong>—downtime means broken links and frustrated users. This goal ensures the system withstands failures, even on a single-node budget.</p><h3 id="strategy-2" tabindex="-1">Strategy <a class="header-anchor" href="#strategy-2" aria-label="Permalink to &quot;Strategy&quot;">​</a></h3><ul><li><strong>LiteFS Replication</strong>: LiteFS, a FUSE-based file system, replicates SQLite across nodes, enhancing availability beyond its single-node roots (<a href="https://github.com/superfly/litefs" target="_blank" rel="noreferrer">LiteFS GitHub</a>). Used in Phase 3, it ensures failover without extra cost.</li><li><strong>Chaos Testing</strong>: Tools like Chaos Mesh simulate failures (e.g., network drops, VM crashes) to validate 99.9% uptime, building resilience into the stack.</li><li><strong>Caching Redundancy</strong>: Redis acts as a first line of defense, serving 99% of requests even if the database lags, minimizing user impact.</li></ul><h3 id="implications-2" tabindex="-1">Implications <a class="header-anchor" href="#implications-2" aria-label="Permalink to &quot;Implications&quot;">​</a></h3><p>This transforms SQLite into a resilient option for distributed systems, proving that reliability doesn’t require expensive infrastructure—just smart engineering.</p><h2 id="_4-learning-focus" tabindex="-1">4. Learning Focus <a class="header-anchor" href="#_4-learning-focus" aria-label="Permalink to &quot;4. Learning Focus&quot;">​</a></h2><h3 id="motivation-3" tabindex="-1">Motivation <a class="header-anchor" href="#motivation-3" aria-label="Permalink to &quot;Motivation&quot;">​</a></h3><p>Beyond functionality, QuickLinker-ZeroRPM is a <strong>learning platform</strong> for system engineers. It explores cost vs. performance trade-offs, preparing for enterprise challenges while documenting real-world scaling tactics.</p><h3 id="strategy-3" tabindex="-1">Strategy <a class="header-anchor" href="#strategy-3" aria-label="Permalink to &quot;Strategy&quot;">​</a></h3><ul><li><strong>SQLite Scalability Case Study</strong>: Tests SQLite’s limits with tuning and caching, challenging its “small app only” reputation (<a href="https://shlink.io/documentation/supported-db-engines/" target="_blank" rel="noreferrer">Shlink Documentation</a>). Results are shared as a resource for others.</li><li><strong>Hands-On Skills</strong>: Engineers gain experience with: <ul><li>Designing cost-efficient stacks (SQLite, free VMs).</li><li>Implementing caching (Redis) to slash database load.</li><li>Building analytics pipelines (Kafka, TimescaleDB in Phase 2).</li><li>Testing resilience (Chaos Mesh in Phase 3).</li></ul></li><li><strong>Open Documentation</strong>: Findings, like SQLite’s 80,000 inserts/second benchmark (<a href="https://news.ycombinator.com/item?id=35547819" target="_blank" rel="noreferrer">Hacker News</a>), are detailed for community learning.</li></ul><h3 id="implications-3" tabindex="-1">Implications <a class="header-anchor" href="#implications-3" aria-label="Permalink to &quot;Implications&quot;">​</a></h3><p>This goal empowers engineers with practical, transferable skills, bridging academic theory and production realities—all within a $0 budget constraint.</p><h2 id="how-these-goals-interconnect" tabindex="-1">How These Goals Interconnect <a class="header-anchor" href="#how-these-goals-interconnect" aria-label="Permalink to &quot;How These Goals Interconnect&quot;">​</a></h2><ul><li><strong>Cost Efficiency enables Scalability</strong>: Free resources force creative optimization, like SQLite tuning and caching, to hit 100,000 RPM.</li><li><strong>Scalability supports Reliability</strong>: A low database load (33 ops/second) simplifies replication and failover with LiteFS.</li><li><strong>Reliability fuels Learning</strong>: Chaos testing and replication experiments yield insights into resilient design.</li><li><strong>Learning ties it together</strong>: Documenting this journey benefits the community while refining the system.</li></ul><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h2><p>These goals unfold across phases:</p><ul><li><strong><a href="./../technical-architecture/phase-1/">Phase 1</a></strong>: Cost-efficient scaling to 100 req/s with SQLite.</li><li><strong><a href="./../technical-architecture/phase-2/">Phase 2</a></strong>: Scalable analytics with Kafka.</li><li><strong><a href="./../technical-architecture/phase-3/">Phase 3</a></strong>: Reliable multi-node resilience.</li></ul><p>Explore the <a href="./../technical-architecture/phase-1/">Technical Architecture</a> for how these goals come to life.</p><hr><p><em>Last Updated: March 11, 2025</em></p>',38)]))}]]);export{r as __pageData,o as default};
